def transform(grid):
    """Recolor any uniform full-width or full-height divider lines to magenta (2)."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    lines = set()
    for r, row in enumerate(out):
        if row and all(v == row[0] for v in row):
            lines.add(("row", r, row[0]))
    for c in range(w):
        vals = [out[r][c] for r in range(h)]
        if vals and all(v == vals[0] for v in vals):
            lines.add(("col", c, vals[0]))
    for axis, i, _ in lines:
        if axis == "row":
            out[i] = [2] * w
        else:
            for r in range(h):
                out[r][i] = 2
    return out
